#' Summary of Continuous Variables
#'
#' 
#' @param data .
#' @param vars .
#' @param distr .
#' @param decimal_places .
#' @param outliers .
#' @param report_sentences .
#' @param show_guidance .
#' @param showplot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$descriptives} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diagnostics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$outlierSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$outlierRows} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$text} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$reportSentences} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$guidance} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$distribution} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$descriptives$asDF}
#'
#' \code{as.data.frame(results$descriptives)}
#'
#' @export
pysummarydata <- function(
    data,
    vars = NULL,
    distr = FALSE,
    decimal_places = 2,
    outliers = FALSE,
    report_sentences = FALSE,
    show_guidance = FALSE,
    showplot = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pysummarydata requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- pysummarydataOptions$new(
        vars = vars,
        distr = distr,
        decimal_places = decimal_places,
        outliers = outliers,
        report_sentences = report_sentences,
        show_guidance = show_guidance,
        showplot = showplot,
        showConsole = showConsole)

    analysis <- pysummarydataClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

